css:
body { 
    font-family: "Traditional Arabic", Tahoma, sans-serif; 
    font-size: 14px; 
    direction: rtl; 
    color: #000; 
} 
.header-table, .info-table, .items-table, .signature-table { 
    width: 100%; 
    border-collapse: collapse; 
    font-size: 14px; 
} 
.items-table { 
    margin-top: 15px; 

} .items-table th, .items-table td { 
    border: 1px solid #000; 
    padding: 5px; 
    text-align: center; 
    vertical-align: middle; 

} .items-table th { 
    background-color: #f2f2f2; 
    font-weight: bold; 

} .section-title { 
    font-size: 24px; 
    text-align: center; 
    margin-top: 5px; 

} hr { 
    border: 0; 
    border-top: 1px solid #000; 
    margin-top: 10px; 
    margin-bottom: 15px; 

} .info-table td { 
    padding: 4px; 
    vertical-align: top; 
    text-align: right;
    }
